import{_ as a,o as r,c as t,a2 as n}from"./chunks/framework.CiQ1TEvV.js";const u=JSON.parse('{"title":"关于 Mneme","description":"","frontmatter":{},"headers":[],"relativePath":"zh/about.md","filePath":"zh/about.md","lastUpdated":1785115728000}'),l={name:"zh/about.md"};function o(i,e,s,h,m,c){return r(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="关于-mneme" tabindex="-1">关于 Mneme <a class="header-anchor" href="#关于-mneme" aria-label="Permalink to &quot;关于 Mneme&quot;">​</a></h1><p>Mneme 是一个本地文档检索增强生成（RAG）系统，以 <strong>Mnemosyne</strong>——希腊神话中的记忆女神——命名。</p><h2 id="项目目标" tabindex="-1">项目目标 <a class="header-anchor" href="#项目目标" aria-label="Permalink to &quot;项目目标&quot;">​</a></h2><p>将本地文档集合变成可验证、可查询的记忆。每个回答都应能追溯到具体的文件、页码和 chunk。</p><h2 id="mneme-是什么" tabindex="-1">Mneme 是什么 <a class="header-anchor" href="#mneme-是什么" aria-label="Permalink to &quot;Mneme 是什么&quot;">​</a></h2><ul><li>一个 <strong>Python CLI</strong>，用于一次性批处理文档问答</li><li>一个 <strong>双语终端 UI</strong>（TUI），用于带文件监听的交互式会话</li><li>一个 <strong>混合检索引擎</strong>，结合语义搜索（ChromaDB + Sentence Transformers）和词法搜索（BM25）</li><li>一个 <strong>Graph RAG</strong> 模式，用于跨文档关系查询</li><li>一个 <strong>安全优先</strong> 的系统，具有显式数据边界、端点验证和资源限制</li></ul><h2 id="mneme-不是什么" tabindex="-1">Mneme 不是什么 <a class="header-anchor" href="#mneme-不是什么" aria-label="Permalink to &quot;Mneme 不是什么&quot;">​</a></h2><ul><li>不是云服务 — 所有索引在本地运行</li><li>不是数据永远不会离开本机的保证 — 检索到的片段会发送到你配置的 LLM 端点</li><li>不是替代阅读原始文档 — 它通过快速检索和摘要增强阅读</li></ul><h2 id="架构原则" tabindex="-1">架构原则 <a class="header-anchor" href="#架构原则" aria-label="Permalink to &quot;架构原则&quot;">​</a></h2><ol><li><strong>身份优先</strong> — 稳定的 <code>source_id</code>、<code>chunk_id</code> 和内容哈希防止索引漂移</li><li><strong>版本化变更</strong> — 原子 manifest 更新保持向量存储、BM25 和图缓存一致</li><li><strong>显式边界</strong> — 不可信文档标签将检索文本与系统指令分离</li><li><strong>可度量质量</strong> — Recall@k、MRR、nDCG 和 quality gate 的 benchmark 工具</li><li><strong>离线安全测试</strong> — CI 无需 API key 运行；集成测试为 opt-in</li></ol><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><p><a href="https://github.com/realhenrylan/mneme/blob/main/LICENSE" target="_blank" rel="noreferrer">MIT License</a></p><h2 id="作者" tabindex="-1">作者 <a class="header-anchor" href="#作者" aria-label="Permalink to &quot;作者&quot;">​</a></h2><p>由 <a href="https://github.com/realhenrylan" target="_blank" rel="noreferrer">Henry Lan</a> 构建。</p><h2 id="链接" tabindex="-1">链接 <a class="header-anchor" href="#链接" aria-label="Permalink to &quot;链接&quot;">​</a></h2><ul><li><a href="https://github.com/realhenrylan/mneme" target="_blank" rel="noreferrer">GitHub 仓库</a></li><li><a href="https://github.com/realhenrylan/mneme/issues" target="_blank" rel="noreferrer">Issues &amp; Discussions</a></li><li><a href="/MNEME/zh/">首页</a></li></ul>',16)])])}const b=a(l,[["render",o]]);export{u as __pageData,b as default};
